-- TORVO V2 secure business action RPCs. Actor identity always comes from auth.uid().
create or replace function set_gst_billing_mode(p_enabled boolean,p_pricing_mode text,p_reason text) returns void language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;s tax_settings%rowtype;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Not authorized';end if;if p_pricing_mode not in('included','extra') or nullif(trim(p_reason),'') is null then raise exception 'Pricing mode and reason required';end if;select * into s from tax_settings where id=true for update;update tax_settings set gst_billing_enabled=p_enabled,default_pricing_mode=p_pricing_mode,updated_by=a.id,updated_at=now() where id=true;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'GST_BILLING_MODE_CHANGED','tax_settings','GLOBAL',jsonb_build_object('old_enabled',s.gst_billing_enabled,'new_enabled',p_enabled,'old_pricing_mode',s.default_pricing_mode,'new_pricing_mode',p_pricing_mode,'reason',trim(p_reason)));end;$$;revoke all on function set_gst_billing_mode(boolean,text,text) from public,anon;grant execute on function set_gst_billing_mode(boolean,text,text) to authenticated;
-- GST invoice can only be generated by Owner/Admin, from a fully paid Estimate, while GST mode is ON.
create or replace function approve_gst_invoice(p_estimate uuid,p_reason text) returns uuid language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;ts tax_settings%rowtype;d sales_documents%rowtype;inv uuid;paid numeric;ln record;taxable numeric;gst numeric;taxable_sum numeric:=0;gst_sum numeric:=0;invoice_sum numeric:=0;serial_no bigint;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin') then raise exception 'Owner/Admin approval required';end if;if nullif(trim(p_reason),'') is null then raise exception 'Approval reason required';end if;select * into ts from tax_settings where id=true;if not found or not ts.gst_billing_enabled then raise exception 'GST billing is OFF';end if;select * into d from sales_documents where id=p_estimate and doc_type='estimate' for update;if not found then raise exception 'Estimate not found';end if;select id into inv from gst_invoices where estimate_id=p_estimate;if inv is not null then raise exception 'GST invoice already exists';end if;select coalesce(sum(amount),0) into paid from payments where estimate_id=p_estimate and status in('cash','received');if paid<d.final_payable then raise exception 'Full payment required before GST invoice approval';end if;serial_no:=issue_final_sale_serial(p_estimate);insert into gst_invoices(estimate_id,status,pricing_mode,torvo_final_serial,approved_by,approved_at) values(p_estimate,'approved',ts.default_pricing_mode,serial_no,a.id,now()) returning id into inv;for ln in select l.*,c.item_code,c.name,c.hsn_code,coalesce(c.gst_rate,0) gst_rate,coalesce(c.gst_mode,ts.default_pricing_mode) line_mode from sales_document_lines l join catalog_items c on c.id=l.item_id where l.document_id=p_estimate loop if ln.line_mode='included' and ln.gst_rate>0 then taxable:=round(coalesce(ln.amount,ln.qty*ln.rate)/(1+ln.gst_rate/100),2);gst:=round(coalesce(ln.amount,ln.qty*ln.rate)-taxable,2);else taxable:=round(coalesce(ln.amount,ln.qty*ln.rate),2);gst:=case when ln.line_mode='extra' then round(taxable*ln.gst_rate/100,2) else 0 end;end if;insert into gst_invoice_lines(invoice_id,item_id,item_code_snapshot,item_name_snapshot,hsn_snapshot,gst_rate_snapshot,qty,rate_snapshot,line_total,taxable_value,gst_amount) values(inv,ln.item_id,ln.item_code,ln.name,ln.hsn_code,ln.gst_rate,ln.qty,ln.rate,round(taxable+gst,2),taxable,gst);taxable_sum:=taxable_sum+taxable;gst_sum:=gst_sum+gst;invoice_sum:=invoice_sum+taxable+gst;end loop;update gst_invoices set taxable_total=round(taxable_sum,2),gst_total=round(gst_sum,2),invoice_total=round(invoice_sum+d.freight+d.other_charges,2) where id=inv;insert into gst_invoice_approval_history(invoice_id,action,reason,actor_id) values(inv,'APPROVED',trim(p_reason),a.id);insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'GST_INVOICE_APPROVED','gst_invoice',inv::text,jsonb_build_object('estimate_id',p_estimate,'torvo_final_serial',serial_no,'reason',trim(p_reason)));return inv;end;$$;revoke all on function approve_gst_invoice(uuid,text) from public,anon;grant execute on function approve_gst_invoice(uuid,text) to authenticated;
-- Final serial is only allocated after full payment. Repeated calls return the same serial.
create or replace function issue_final_sale_serial(p_estimate uuid) returns bigint language plpgsql security definer set search_path=public as $$declare a app_users%rowtype;d sales_documents%rowtype;n bigint;paid numeric;begin select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role not in('owner','admin','accountant') then raise exception 'Not authorized';end if;select * into d from sales_documents where id=p_estimate and doc_type='estimate' for update;if not found then raise exception 'Estimate not found';end if;if d.final_sale_serial is not null then return d.final_sale_serial;end if;select coalesce(sum(amount),0) into paid from payments where estimate_id=p_estimate and status in('cash','received');if paid<d.final_payable then raise exception 'Full payment not received';end if;n:=nextval('final_sale_serial_seq');update sales_documents set final_sale_serial=n,final_sale_serial_issued_at=now() where id=p_estimate;insert into audit_log(actor_id,action,entity_type,entity_id,details) values(a.id,'FINAL_SALE_SERIAL_ISSUED','estimate',p_estimate::text,jsonb_build_object('serial',n));return n;end;$$;revoke all on function issue_final_sale_serial(uuid) from public,anon;grant execute on function issue_final_sale_serial(uuid) to authenticated;
